public sealed record HelpArticle(string Section, string Title, string Text, string Where = "", string Page = "", params HotkeyAction[] Keys)
{
    public string[] Images { get; init; } = Array.Empty<string>();

    public string Limit { get; init; } = "";

    public string PlainText => HelpText.Plain(Text);
}

