            "Напиши разработчику, ссылки есть внизу окна настроек. Приложи файл журнала log.txt из папки %AppData%\\StreamHelper. Ключей и паролей в нём нет, так что отправлять его можно спокойно."),
    };

    public static IEnumerable<HelpArticle> InSection(string section) => Articles.Where(a => a.Section == section);

    public static IReadOnlyList<HelpArticle> Search(string query)
    {
        var words = query.Split(' ', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries);
        if (words.Length == 0) return Articles;
        return Articles
            .Where(a => words.All(w => Contains(a.Title, w) || Contains(a.PlainText, w) || Contains(a.Where, w) || Contains(a.Section, w) || Contains(a.Limit, w)))
            .OrderByDescending(a => words.Count(w => Contains(a.Title, w)))
            .ToList();
    }

    private static bool Contains(string text, string word) => text.Contains(word, StringComparison.CurrentCultureIgnoreCase);
}
